args.sparql:
SELECT DISTINCT ?father ?fatherLabel WHERE {
  { dbr:Bohemond_IV_of_Antioch dbp:father ?father } UNION { dbr:Bohemond_IV_of_Antioch dbo:parent ?father } .
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER(lang(?fatherLabel) = 'en') }
}

SELECT DISTINCT ?grandfather ?grandfatherLabel WHERE {
  { dbr:Bohemond_III_of_Antioch dbp:father ?grandfather } UNION { dbr:Bohemond_III_of_Antioch dbo:parent ?grandfather } .
  OPTIONAL { ?grandfather rdfs:label ?grandfatherLabel . FILTER(lang(?grandfatherLabel) = 'en') }
}

